    """Map a signed int to a non-negative int.

    Unlike the classic `(n << 1) ^ (n >> 63)` formula, this works for
    arbitrarily large Python ints (no fixed word size).
    """
    return n << 1 if n >= 0 else (-n << 1) - 1


def _zigzag_decode(raw: int) -> int:
    return (raw >> 1) if not raw & 1 else -((raw + 1) >> 1)


def encode_zigzag(n: int) -> bytes:
    """ZigZag-encode a signed int, then varint-encode it."""
