result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_varint.py", "content": "import pytest
from hypothesis import given, strategies as st

from varint import (
    decode_uvarint,
    decode_zigzag,
    encode_uvarint,
    encode_zigzag,
    pack_ints,
    unpack_ints,
)

# Arbitrary non-negative ints up to 2^70 (and beyond via max_value slack)
u64plus = st.integers(min_value=0, max_value=2 ** 70)
signed_any = st.integers()


class TestUVarintRoundTrip:
    @given(u64plus)
    def test_round_trip(self, n):
        buf = encode_uvarint(n)
        value, offset = decode_uvarint(buf)
        assert value == n
        assert offset == len(buf)

    @given(st.integers(min_value=0))
    def test_round_trip_unbounded(self, n):
        # even way past 2^70 it must hold
        buf = encode_uvarint(n)
        assert decode_uvarint(buf) == (n, len(buf))


class TestSmallValuesShort:
    @given(st.integers(min_value=0, max_value=127))
    def test_one_byte(self, n):
        assert encode_uvarint(n) == bytes([n])
        assert len(encode_uvarint(n)) == 1

    @given(st.integers(min_value=128, max_value=16383))
    def test_two_bytes(self, n):
        assert len(encode_uvarint(n)) == 2


class TestTruncationRaises:
    @given(u64plus.filter(lambda n: n >= 128))
    def test_chopped_last_byte_raises(self, n):
        buf = encode_uvarint(n)
        assert len(buf) > 1  # multi-byte by construction
        with pytest.raises(ValueError):
            decode_uvarint(buf[:-1])

    def test_empty_buffer_raises(self):
        with pytest.raises(ValueError):
            decode_uvarint(b"")


class TestZigZag:
    @given(signed_any)
    def test_round_trip(self, n):
        buf = encode_zigzag(n)
        assert decode_zigzag(buf) == (n, len(buf))

    @given(signed_any)
    def test_encoding_is_nonnegative_varint(self, n):
        raw, _ = decode_uvarint(encode_zigzag(n))
        assert raw >= 0

    @given(st.sampled_from([0, -1, 1, -2, 2, -64, 63]))
    def test_known_mappings(self, pair):
        pass  # replaced below


def test_known_zigzag_values():
    assert decode_uvarint(encode_zigzag(0))[0] == 0
    assert decode_uvarint(encode_zigzag(-1))[0] == 1
    assert decode_uvarint(encode_zigzag(1))[0] == 2
    assert decode_uvarint(encode_zigzag(-2))[0] == 3


class TestPackUnpack:
    @given(st.lists(signed_any))
    def test_round_trip(self, xs):
        assert unpack_ints(pack_ints(xs)) == xs

    @given(st.lists(u64plus.map(lambda n: n - 2 ** 69), min_size=1))
    def test_round_trip_huge_magnitudes(self, xs):
        assert unpack_ints(pack_ints(xs)) == xs

    def test_empty(self):
        assert pack_ints([]) == b""
        assert unpack_ints(b"") == []


class TestConcatenation:
    @given(
        st.lists(st.tuples(signed_any, signed_any), min_size=1),
    )
    def test_concatenated_encodings_decode_sequentially(self, pairs):
        bufs_a = [encode_uvarint(abs(a)) for a, _ in pairs]
        bufs_b = [encode_uvarint(abs(b)) for _, b in pairs]
        joined = b"".join(bufs_a + bufs_b)
        values = []
        offset = 0
        while offset < len(joined):
            v, offset = decode_uvarint(joined, offset)
            values.append(v)
        expected = [abs(a) for a, _ in pairs] + [abs(b) for _, b in pairs]
        assert values == expected

    @given(st.lists(signed_any, min_size=2))
    def test_packed_streams_split_correctly(self, xs):
        packed = pack_ints(xs)
        mid = len(xs) // 2
        left, right = pack_ints(xs[:mid]), pack_ints(xs[mid:])
        assert left + right == packed

        vals = []
        offset = 0
        for _ in range(mid):
            v, offset = decode_zigzag(packed, offset)
            vals.append(v)
        assert vals == xs[:mid]
        rest, final_offset = [], offset
        while final_offset < len(packed):
            v, final_offset = decode_zigzag(packed, final_offset)
            rest.append(v)
        assert rest == xs[mid:]


def test_known_wire_bytes_300():
    assert encode_uvarint(300) == b"\xac\x02"
